function rail(active, no){return `<div class="rail">${modules.map(m=>`<p class="${m.key===active?'active':''}">${m.label}</p>`).join('')}<p class="page">${String(no).padStart(2,'0')}</p></div>`}
let renderedPageNo=0;
function page({no,active='setup',kicker='',title='',subtitle='',content='',dark=false,source=''}){const actualNo=++renderedPageNo;return `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>${css}</style></head><body class="${dark?'dark':''}" data-module="${active}">${dark?'':rail(active,actualNo)}${title?`<div class="title">${kicker?`<p class="kicker">${kicker}</p>`:''}<h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>`:''}${content}${source?`<p class="source-note">${source}</p>`:''}</body></html>`}
function section(no,moduleNo,title,sub){const active={"01":"setup","02":"ui","03":"data","04":"deploy"}[moduleNo]||'setup';return page({no,active,dark:true,content:`<p class="section-no">MODULE ${moduleNo}</p><h1 class="section-title">${title}</h1><p class="section-sub">${sub}</p><div class="section-line"></div>`})}
function code(lines,compact=false){return `<div class="code${compact?' compact':''}"><div class="bar"><i class="dot"></i><i class="dot"></i><i class="dot"></i></div><pre>${lines}</pre></div>`}
function prompt(label,text,foot='붙여넣기 → 제안 파일 확인 → 승인 → 검증',compact=false){return `<div class="prompt${compact?' compact':''}"><div class="prompt-head"><strong>${label}</strong><span>CLAUDE CODE</span></div><div class="prompt-text">${text}</div><div class="prompt-foot">${foot}</div></div>`}
function browserForm(rows,button='등록'){return `<div class="browser"><div class="browser-top">🔒 opendart.fss.or.kr</div><div class="browser-body"><div class="sitebar"><strong>OPEN DART</strong><span class="menu">오픈API 소개　 인증키 신청/관리　 개발가이드</span></div><div class="mock-form">${rows.map(([k,v])=>`<div class="mock-row"><b>${k}</b><span>${v}</span></div>`).join('')}</div>${button?`<span class="mock-button">${button}</span>`:''}</div></div>`}

const P={
  analyze:`이 저장소를 먼저 분석해줘. 아직 코드는 수정하지 마.\n\n1. 실행 진입점\n2. 화면 파일\n3. OpenDART 호출 위치\n4. 지표 계산 위치\n5. Vercel 배포 파일\n\n각 파일의 역할과 다음에 수정할 순서를 설명해줘.`,
  uiPlan:`HR Analytics 기본 화면을 만들려고 해.\n아직 수정하지 말고 계획만 작성해줘.\n\n필수 요소: 기업 검색, 선택 기업 2개, 기준연도,\n보고서 종류, 비교 버튼, 결과 영역.\n\n변경 파일·구현 순서·완료 기준을 표로 보여줘.`,
  uiShell:`계획의 첫 단계만 구현해줘.\n\nstatic/index.html과 static/styles.css에\n- 서비스 제목과 한 줄 소개\n- 기업 검색 입력창\n- 선택 기업 영역\n- 결과가 아직 없다는 안내\n를 만들어줘. 실제 API와 선택 동작은 아직 넣지 마.`,
  addSelection:`방금 만든 화면에 기업 선택 동작을 추가해줘.\n\n- 검색 결과를 임시 샘플 3개로 보여준다.\n- 최대 2개를 추가·삭제할 수 있다.\n- 중복 선택을 막는다.\n- 선택 수를 0/2처럼 표시한다.\n\n기존 화면 스타일과 파일 구조를 유지해줘.`,
  addPeriod:`기업 선택 기능은 그대로 두고 다음 기능만 추가해줘.\n\n- 기준연도 선택\n- 사업·반기·분기보고서 선택\n- 인력·보상 비교 버튼\n- 조건이 바뀌면 이전 결과 비우기\n\n아직 OpenDART와 AI는 호출하지 마.`,
  fix:`현재 화면과 터미널 오류를 읽어줘.\n원인 후보를 3개 이내로 좁힌 뒤 가장 작은 수정부터 적용해줘.\n수정 전 재현 조건, 수정 파일, 수정 후 확인 결과를 정리해줘.\n관련 없는 파일은 바꾸지 마.`,
  dartPlan:`선택 기업·연도·보고서로 직원수, 평균급여,\n매출액, 영업이익을 조회하려고 해.\n\n아직 수정하지 말고 사용할 OpenDART API, 요청값,\n서버 경로, 변경 파일, 결측 처리, 검증 방법을 설계해줘.`,
  env:`현재 Starter의 OPENDART_API_KEY 처리 경계를 점검해줘.\n계약을 만족하지 않는 부분만 수정해줘.\n\n- 실제 키를 코드·로그·응답에 넣지 않는다.\n- .env.example에는 변수 이름만 둔다.\n- .env가 Git에서 제외되는지 확인한다.\n- /api/health에는 설정 여부만 반환한다.\n\n검사 명령과 결과도 보여줘.`,
  corp:`기업 검색창을 /api/companies에 연결해줘.\n두 글자 이상 입력하면 검색하고 기업명·종목코드를 보여줘.\n선택하면 corp_code를 상태에 저장해줘.\n검색 중·결과 없음·오류를 구분하고 중복 선택을 막아줘.`,
  fetch:`선택 기업의 corp_code, 연도, 보고서 코드로\n재무정보와 직원현황을 함께 조회해줘.\n\n매출액·영업이익·직원수·평균급여를 corp_code로 결합하고,\n키는 브라우저로 보내지 마. 로딩·결측·오류를 구분해줘.`,
  missing:`공시 데이터 품질 규칙을 적용해줘.\n\n- 데이터 없음은 0으로 바꾸지 않는다.\n- 실제 0과 결측을 화면에서 구분한다.\n- 단위·기준연도·보고서·연결/별도 범위를 표시한다.\n- 각 값에 evidence_id를 연결한다.`,
  metric:`별도 함수로 다음 지표를 계산해줘.\n1. 인당 매출 = 매출액 / 직원수\n2. 인당 영업이익 = 영업이익 / 직원수\n3. 직원수 증가율\n4. 평균급여 증가율\n\n결측·분모 0이면 계산하지 마.\ntests/test_workforce_analytics.py에 정상값, 직원수 결측, 분모 0,\n영업이익 음수 테스트를 만들고 실행 결과를 보여줘.`,
  payload:`AI에게 원문 전체를 보내지 말고 다음만 담은 payload를 만들어줘.\n- 선택 기업과 기준연도\n- 검증된 원자료\n- 계산된 HR 지표\n- evidence_ids\n- 사용자 질문\n\n전송 전에 스키마를 검증하고 키·개인정보는 제외해줘.`,
  ai:`HR Analytics Assistant를 구현해줘.\n\n연결 계약:\n- 브라우저는 POST /api/ai/briefing으로 검증된 payload만 보낸다.\n- Provider는 OpenAI Responses API이며 모델은 OPENAI_MODEL을 사용한다.\n- 개인 키는 password 입력 → X-OpenAI-API-Key 헤더 → 서버 요청 메모리에서만 사용한다.\n- 개인 키가 없으면 서버의 OPENAI_API_KEY를 사용한다.\n- 키를 localStorage·로그·응답·오류문에 저장하거나 출력하지 않는다.\n\n답변을 확인된 사실, 계산 결과, 해석, 추가 확인 정보로 구분해줘.\n공시만으로 인과관계를 단정하거나 개인 평가·채용·보상·감축을 권고하지 못하게 하고,\n근거 ID와 한계를 표시해줘. 연결 실패·인증 실패·모델 실패도 구분해줘.`,
};

