for(const file of fs.readdirSync(deckDir)){if(/^slide-\d+\.html$/.test(file))fs.unlinkSync(path.join(deckDir,file))}
slides.forEach((html,index)=>fs.writeFileSync(path.join(deckDir,`slide-${String(index+1).padStart(2,'0')}.html`),html,'utf8'));

const titles=slides.map((html,index)=>{
  const match=html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
  return match ? match[1].replace(/<br\s*\/?\s*>/gi,' ').replace(/<[^>]+>/g,'').trim() : `실습 단계 ${index+1}`;
});
const outline=`# DART API부터 배포까지 직접 만들어가기\n\n## Meta\n- Slide count: ${slides.length}\n- Aspect ratio: 16:9\n- Teaching model: 화면 설명이 아니라 실제 제작 순서 재현\n- Core loop: 프롬프트 → 변경 파일 → diff → 실행 → 체크포인트\n\n## Slide map\n${titles.map((t,i)=>`- ${String(i+1).padStart(2,'0')}. ${t}`).join('\n')}\n`;
fs.writeFileSync(path.join(deckDir,'slide-outline.md'),outline,'utf8');

const promptDoc=`# 수강생용 Claude Code 실습 프롬프트\n\n아래 프롬프트를 순서대로 사용합니다. 실제 API 키는 어떤 프롬프트에도 입력하지 않습니다. 각 단계에서 Claude가 제안한 변경 파일을 확인하고, 적용 뒤에는 반드시 \`git diff\`와 브라우저를 확인합니다.\n\n${Object.entries(P).map(([key,value],index)=>`## ${String(index+1).padStart(2,'0')}. ${key}\n\n\`\`\`text\n${value}\n\`\`\``).join('\n\n')}\n\n## 공통 검증 프롬프트\n\n\`\`\`text\n방금 변경한 내용을 검증해줘. 수정 파일 목록, 실행한 검사, 통과 결과, 아직 남은 위험을 구분해서 보여줘. 실제 API 키나 개인정보는 출력하지 마.\n\`\`\`\n\n## 오류 수정 프롬프트\n\n\`\`\`text\n${P.fix}\n\`\`\`\n`;
fs.writeFileSync(path.join(deckDir,'participant-prompts.md'),promptDoc,'utf8');

const moduleActions={
  setup:'수강생 화면에서 계정·키·.env·서버·Claude 입력을 직접 따라 하게 합니다.',
  ui:'프롬프트를 붙여넣고 계획·변경 파일·diff·브라우저 결과를 차례로 확인합니다.',
  data:'OpenDART 연결, 결측, 계산, AI Provider 경로를 한 기능씩 구현하고 매번 실행합니다.',
  deploy:'GitHub와 Vercel에서 실제 URL이 생길 때까지 진행하고 원격 commit을 대조합니다.',
};
const notes=`# 발표자 노트\n\n이 덱은 완성 프로그램 소개 자료가 아니라 실습 진행 화면입니다. 각 슬라이드에서 강사는 먼저 직접 입력하고, 수강생이 같은 조작을 끝낸 뒤 다음 장으로 이동합니다.\n\n${titles.map((t,i)=>{const no=i+1;const module=slides[i].match(/data-module="([^"]+)"/)?.[1]||'setup';const action=no<=5?'강의 목표와 제출 증거를 짧게 확인합니다.':moduleActions[module];return `## ${String(no).padStart(2,'0')}. ${t}\n${action}`}).join('\n\n')}\n`;
fs.writeFileSync(path.join(deckDir,'speaker-notes.md'),notes,'utf8');

const quick=`# 강의 바로 시작\n\n1. 도입에서는 오늘 만들 순서와 제출 증거만 확인하고 완성 화면은 2분 안에 닫습니다.\n2. MODULE 01에서 OpenDART 키 발급, .env 입력, 서버와 Claude Code 실행을 화면 공유하며 직접 시연합니다.\n3. MODULE 02에서는 전체 프롬프트를 한 개씩 붙여넣고 화면 뼈대→기업 선택→기간 선택이 자라는 과정을 확인합니다.\n4. MODULE 03에서는 브라우저→Python 서버→OpenDART와 AI Provider 요청을 코드·URL·JSON으로 확인한 뒤 지표와 브리핑을 추가합니다.\n5. MODULE 04에서 GitHub와 Vercel을 실제로 연결하고 공개 URL에서 같은 조작을 재현합니다.\n\n## 화면 공유 원칙\n- 실제 API 키, .env 값, 요청 헤더는 공유하지 않습니다.\n- 강사는 키를 미리 설정한 별도 데모 환경을 사용합니다.\n- 외부 API가 실패하면 저장소 루트의 검증된 완성본과 준비된 응답 캡처로 설명을 이어가고, 수강생 작업은 보존합니다.\n`;
fs.writeFileSync(path.join(deckDir,'강의_바로시작.md'),quick,'utf8');

